//! Wire protocol: generated protobuf types plus length-delimited framing.
//!
//! Unix sockets and SSH stdio carry the exact same stream:
//! `envelope_length:u32` in network byte order followed by one serialized
//! `WireEnvelope`. The framing stays transport-portable.

pub mod framing;
pub mod ids;

/// Generated protobuf types.
pub mod v1 {
    // Generated by prost from proto/farcooler.proto. Its enum layouts are
    // prost's business, not ours, and there is nothing to act on here.
    #![allow(clippy::large_enum_variant)]

    include!(concat!(env!("OUT_DIR"), "/farcooler.v1.rs"));
}

pub use v1::*;

/// Protocol major version this build speaks.
pub const PROTOCOL_VERSION: u32 = 1;

/// Which source this binary was built from: `0.1.0+a1b2c3d`, `-dirty` if the
/// worktree had uncommitted changes.
///
/// Reported by the daemon in every handshake and sent by every client in its
/// own, so that two components built from different source SAY so rather than
/// disagreeing silently — which is exactly how a fixed bug goes on reproducing.
/// `PROTOCOL_VERSION` answers "can these talk"; this answers "are these the
/// same build", and they are different questions.
pub const BUILD: &str = env!("FARCOOLER_BUILD");

/// Which installation this build belongs to.
///
/// Four channels are four separate installs that coexist on one host —
/// separate runtime directory, database, tmux server, binary name and bundle
/// identifier — so this is not a label. It decides where the daemon lives.
///
/// The names are the ones a developer tool audience already knows: `nightly`
/// and `canary` and `stable` mean the same things in Rust, Chrome and Zed as
/// they mean here.
///
/// Compile time, never a flag someone types. `scripts/version.sh` makes the
/// same call about the channel it derives: "a flag is a thing to forget on the
/// build that mattered." A daemon that could be told which channel it is could
/// be told wrong, and being wrong means a preview build writing into the stable
/// database.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Channel {
    /// Built on somebody's machine. Nothing is settled and nothing is promised.
    Local,
    /// Every push to `main`, published to internal testers automatically. The
    /// build that breaks first so the others do not.
    Canary,
    /// A `-preview.N` tag, for external testers.
    Preview,
    /// A release tag. What everyone else runs.
    Stable,
}

impl Channel {
    pub fn as_str(self) -> &'static str {
        match self {
            Channel::Local => "local",
            Channel::Canary => "canary",
            Channel::Preview => "preview",
            Channel::Stable => "stable",
        }
    }

    /// Anything unrecognized is `local`.
    ///
    /// The safe direction, and the reason it is worth stating: a local build
    /// isolates itself from everything, so guessing wrong costs a separate
    /// empty fleet. Guessing `stable` wrong costs someone else's.
    pub fn from_str_or_local(s: &str) -> Self {
        Self::from_str_or_local_const(s)
    }

    /// What this channel's daemon is called on disk.
    ///
    /// The SCHEME is frozen, not the literal: `farcoolerd[-<channel>]`. An App
    /// Store binary hardcodes the path it asks a runner for, which makes the
    /// shape of this name as public as any proto message — and stable's has no
    /// suffix precisely so that every client already in the field keeps
    /// resolving exactly what it always did.
    pub fn daemon_binary_name(self) -> &'static str {
        match self {
            Channel::Stable => "farcoolerd",
            Channel::Preview => "farcoolerd-preview",
            Channel::Canary => "farcoolerd-canary",
            Channel::Local => "farcoolerd-local",
        }
    }

    /// What this channel's CLI is called on disk. Same rule as the daemon's.
    pub fn cli_binary_name(self) -> &'static str {
        match self {
            Channel::Stable => "farcooler",
            Channel::Preview => "farcooler-preview",
            Channel::Canary => "farcooler-canary",
            Channel::Local => "farcooler-local",
        }
    }

    /// The names this channel's daemon may go by on disk, most specific first.
    ///
    /// Two names, because two different things produce a Far Cooler binary and
    /// only one of them renames. `runner install` writes `daemon_binary_name()`
    /// on the destination, which is what lets four channels share one
    /// `~/.local/bin`. Cargo does not: `[[bin]] name = "farcoolerd"` is what
    /// comes out of `target/` no matter which channel stamped it, and
    /// `build-linux.sh`, `release.yml` and the macOS `build-app.sh` all copy
    /// that name along unchanged. Anything asking "where is the daemon that
    /// belongs to me" therefore has to accept both, or a checkout stops being
    /// able to run what it just built the moment it is not stable.
    ///
    /// The order is the safety property, not a preference: a directory holding
    /// both `farcoolerd` and `farcoolerd-preview` must answer a preview client
    /// with the preview daemon. Checking the bare name first would quietly
    /// hand it the stable one, which is the exact meeting these names exist to
    /// prevent.
    ///
    /// Use this to FIND a binary. Use `daemon_binary_name` to NAME one — an
    /// install has a single correct answer and no fallback.
    pub fn daemon_binary_candidates(self) -> &'static [&'static str] {
        match self {
            Channel::Stable => &["farcoolerd"],
            Channel::Preview => &["farcoolerd-preview", "farcoolerd"],
            Channel::Canary => &["farcoolerd-canary", "farcoolerd"],
            Channel::Local => &["farcoolerd-local", "farcoolerd"],
        }
    }

    /// The names this channel's CLI may go by on disk. Same rule as the
    /// daemon's.
    pub fn cli_binary_candidates(self) -> &'static [&'static str] {
        match self {
            Channel::Stable => &["farcooler"],
            Channel::Preview => &["farcooler-preview", "farcooler"],
            Channel::Canary => &["farcooler-canary", "farcooler"],
            Channel::Local => &["farcooler-local", "farcooler"],
        }
    }

    /// The same rule in a form a `const` can call.
    ///
    /// `match` on a `&str` is not permitted in a const context, so this matches
    /// on bytes. One implementation with two entry points rather than two
    /// implementations: the round-trip test covers both.
    const fn from_str_or_local_const(s: &str) -> Self {
        match s.as_bytes() {
            b"stable" => Channel::Stable,
            b"preview" => Channel::Preview,
            b"canary" => Channel::Canary,
            _ => Channel::Local,
        }
    }
}

/// The channel this binary was built for, stamped by `build.rs`.
pub const CHANNEL: Channel = Channel::from_str_or_local_const(env!("FARCOOLER_CHANNEL"));

/// What a daemon can do, by name.
///
/// The mechanism that lets an app and a daemon drift apart, and the reason
/// `PROTOCOL_VERSION` above is expected never to move. A client that needs to
/// know whether a feature exists asks for it BY NAME rather than by comparing
/// version strings — no arithmetic, no compatibility matrix, and a name that
/// has shipped is permanent.
///
/// One table with three consumers: the daemon builds `ServerHello.capabilities`
/// and `DaemonVersion.capabilities` from it, and the CLI reports it. A second
/// copy is exactly the drift this exists to prevent.
///
/// Named per user-visible FEATURE, not per method. A client asks "does this
/// runner do stacks", never "does it implement stack.set_parent".
pub mod capability {
    /// Workspaces, repositories and roots. The floor: a daemon without this is
    /// not a daemon, and every build that has ever existed has it.
    pub const WORKSPACES: &str = "workspaces";
    /// Terminals, their screens and their input. Also the floor.
    pub const TERMINALS: &str = "terminals";
    /// Agent pane mode: the structured conversation, its prompts and its queue.
    pub const AGENT: &str = "agent";
    /// The review surface: change sets, diffs, commits, the inbox.
    pub const CHANGES: &str = "changes";
    /// Stacked branches and their pull requests.
    pub const STACK: &str = "stack";
    /// tmux tiling driven from a client.
    pub const LAYOUT: &str = "layout";
    /// Pasting a file into a terminal.
    pub const PASTE: &str = "paste";
    /// Reading and writing adapter configuration.
    pub const ADAPTERS: &str = "adapters";
    /// Themes and runner settings.
    pub const THEMES: &str = "themes";
    /// Reading, adding and removing the device keys in this runner's fence.
    ///
    /// Its own capability rather than part of `THEMES`: an app that cannot
    /// enroll on a runner has to say so before the ceremony starts, not after
    /// the user has scanned a code.
    pub const ENROLLMENT: &str = "enrollment";

    /// Every capability this build has, in a stable order.
    ///
    /// Stable so that two daemons of the same build produce byte-identical
    /// hellos, which makes the list diffable in a log.
    pub const ALL: &[&str] =
        &[WORKSPACES, TERMINALS, AGENT, CHANGES, STACK, LAYOUT, PASTE, ADAPTERS, THEMES, ENROLLMENT];

    /// The capability a method belongs to, or `None` if there is no such
    /// method.
    ///
    /// Exhaustive by construction, exactly as the daemon's `required_scope` is:
    /// a method with no row here is unreachable rather than silently ungated,
    /// so adding a handler without adding a row fails loudly in tests instead
    /// of shipping an unnamed feature.
    pub fn for_method(method: &str) -> Option<&'static str> {
        Some(match method {
            "host.get" | "host.health" | "daemon.version" | "daemon.shutdown" => WORKSPACES,
            "repository.list"
            | "repository.register"
            | "repository_root.list"
            | "repository_root.add"
            | "repository_root.remove"
            | "workspace.list"
            | "workspace.create"
            | "workspace.hide"
            | "workspace.unhide"
            | "workspace.remove_worktree"
            | "branch.list"
            | "worktree.list"
            | "worktree.file_search" => WORKSPACES,
            "terminal.list"
            | "terminal.create"
            | "terminal.screen"
            | "terminal.write"
            | "terminal.resize"
            | "terminal.stop"
            | "terminal.seen"
            | "terminal.remove"
            | "terminal.dismiss_lost"
            | "terminal.restart" => TERMINALS,
            "terminal.paste_file" => PASTE,
            "terminal.set_pane_mode"
            | "terminal.agent_subscribe"
            | "terminal.agent_prompt"
            | "terminal.agent_answer"
            | "terminal.agent_set_mode"
            | "terminal.agent_set_model"
            | "terminal.agent_set_config"
            | "terminal.agent_edit_queued"
            | "terminal.agent_cancel_queued"
            | "terminal.agent_steer_queued"
            | "terminal.agent_cancel" => AGENT,
            "changes.change_set"
            | "changes.commit_files"
            | "changes.file_diff"
            | "changes.set_base"
            | "changes.mark_read"
            | "changes.inbox" => CHANGES,
            "stack.get" | "stack.set_parent" | "pr.refresh" => STACK,
            m if m.starts_with("layout.") => LAYOUT,
            "adapter.list" | "adapter.upsert" | "adapter.delete" | "adapter.test" => ADAPTERS,
            "theme.list" | "theme.upsert" | "theme.delete" | "settings.set_branch_prefix" => THEMES,
            "client.list" | "client.enroll" | "client.revoke" => ENROLLMENT,
            _ => return None,
        })
    }
}

/// Control envelopes are capped at 1 MiB.
pub const MAX_CONTROL_ENVELOPE_BYTES: usize = 1024 * 1024;

/// `TerminalFrame.payload` is capped at 64 KiB.
pub const MAX_TERMINAL_PAYLOAD_BYTES: usize = 64 * 1024;

/// One chunk of a file being pasted into a terminal.
///
/// Twice a terminal frame and an eighth of the envelope ceiling: big enough
/// that a 16 MiB file is 128 round trips rather than a thousand, small enough
/// that live output interleaves between chunks instead of waiting behind one.
pub const PASTE_CHUNK_BYTES: usize = 128 * 1024;

/// The largest file a client may paste into a terminal.
///
/// Larger than any screenshot or ordinary document, and small enough that a
/// failed transfer costs seconds rather than minutes. Checked on both sides:
/// the client refuses before uploading anything, the daemon before writing it.
pub const MAX_PASTE_FILE_BYTES: u64 = 16 * 1024 * 1024;

/// Each terminal retains the most recent 8 MiB of its current epoch.
pub const REPLAY_BUFFER_BYTES: u64 = 8 * 1024 * 1024;

/// Per-client terminal output window: unacknowledged data cap.
pub const MAX_UNACKED_TERMINAL_BYTES: u64 = 1024 * 1024;

/// Control channel ceiling: queued unwritten control envelopes per client.
pub const MAX_QUEUED_CONTROL_BYTES: u64 = 4 * 1024 * 1024;

/// Clients acknowledge at 256 KiB unacknowledged or 250 ms, whichever first,
/// and always within 1 s of output that leaves anything unacknowledged.
pub const FLOW_ACK_BYTES_THRESHOLD: u64 = 256 * 1024;
pub const FLOW_ACK_INTERVAL_MS: u64 = 250;
pub const FLOW_ACK_MAX_DELAY_MS: u64 = 1000;

/// A disconnected writer lease expires after 30 seconds.
pub const WRITER_LEASE_EXPIRY_SECS: u64 = 30;

/// Terminal dimensions are clamped to these ranges.
pub const MIN_COLUMNS: u32 = 20;
pub const MAX_COLUMNS: u32 = 500;
pub const MIN_ROWS: u32 = 5;
pub const MAX_ROWS: u32 = 200;

#[cfg(test)]
mod tests {
    use super::*;

    /// Every channel, so a match arm added to one list and forgotten in another
    /// fails here rather than shipping.
    const ALL_CHANNELS: [Channel; 4] =
        [Channel::Local, Channel::Canary, Channel::Preview, Channel::Stable];

    #[test]
    fn a_channel_round_trips_through_its_name() {
        for c in ALL_CHANNELS {
            assert_eq!(Channel::from_str_or_local(c.as_str()), c);
        }
    }

    #[test]
    fn an_unknown_channel_is_local_not_stable() {
        // Defaulting the other way would let a hand-made build pass itself off
        // as a release. scripts/version.sh makes the same choice for the same
        // reason.
        assert_eq!(Channel::from_str_or_local(""), Channel::Local);
        assert_eq!(Channel::from_str_or_local("nonsense"), Channel::Local);
        assert_eq!(Channel::from_str_or_local("STABLE"), Channel::Local);
        // The names this replaced. A build stamped by an older checkout must
        // not silently land on the wrong channel — `local` is where anything
        // unreadable belongs.
        assert_eq!(Channel::from_str_or_local("release"), Channel::Local);
        assert_eq!(Channel::from_str_or_local("beta"), Channel::Local);
        assert_eq!(Channel::from_str_or_local("dev"), Channel::Local);
    }

    #[test]
    fn the_stamped_channel_is_one_of_the_four() {
        assert!(ALL_CHANNELS.contains(&CHANNEL));
    }

    #[test]
    fn every_capability_a_method_names_is_one_this_build_advertises() {
        // A method mapped to a capability absent from `ALL` would be
        // permanently unreachable: the daemon refuses anything whose capability
        // it does not advertise, so the typo would present as a feature that
        // silently does not exist.
        for method in [
            "workspace.create",
            "terminal.create",
            "terminal.paste_file",
            "terminal.agent_prompt",
            "changes.file_diff",
            "stack.get",
            "layout.split",
            "adapter.list",
            "theme.list",
            "client.enroll",
        ] {
            let cap = capability::for_method(method).expect("a known method");
            assert!(capability::ALL.contains(&cap), "{method} names {cap}, which is not advertised");
        }
    }

    #[test]
    fn an_unknown_method_names_no_capability() {
        // What makes "this runner is too old" distinguishable from "no such
        // thing": a method nobody implements has no capability, and the daemon
        // turns that into CAPABILITY_UNSUPPORTED rather than NOT_FOUND.
        assert_eq!(capability::for_method("something.invented"), None);
        assert_eq!(capability::for_method(""), None);
    }

    #[test]
    fn the_floor_capabilities_are_always_present() {
        // Every daemon that has ever existed does workspaces and terminals, so
        // a client may assume them without asking. If either ever left this
        // list, every shipped client would break at once.
        assert!(capability::ALL.contains(&capability::WORKSPACES));
        assert!(capability::ALL.contains(&capability::TERMINALS));
    }

    #[test]
    fn capability_names_are_unique() {
        let unique: std::collections::BTreeSet<_> = capability::ALL.iter().collect();
        assert_eq!(unique.len(), capability::ALL.len(), "a duplicate name hides one of them");
    }

    #[test]
    fn release_binaries_keep_their_bare_names() {
        // Every release client already in the field resolves
        // `~/.local/bin/farcoolerd`. A suffix here strands all of them at once,
        // and an App Store build cannot be corrected for days.
        assert_eq!(Channel::Stable.daemon_binary_name(), "farcoolerd");
        assert_eq!(Channel::Stable.cli_binary_name(), "farcooler");
    }

    #[test]
    fn each_channel_has_its_own_binary_name() {
        for names in [
            ALL_CHANNELS.map(Channel::daemon_binary_name),
            ALL_CHANNELS.map(Channel::cli_binary_name),
        ] {
            let unique: std::collections::BTreeSet<_> = names.iter().collect();
            assert_eq!(unique.len(), ALL_CHANNELS.len(), "two channels cannot share one path: {names:?}");
        }
    }

    #[test]
    fn a_lookup_prefers_this_channels_name_over_the_bare_one() {
        // The order is the whole isolation property. A `~/.local/bin` holding
        // both a stable install and a preview one holds two files, and a
        // preview client that checked the bare name first would find the
        // stable daemon sitting there and talk to it — which is precisely the
        // meeting the channels exist to prevent.
        for c in ALL_CHANNELS {
            assert_eq!(c.daemon_binary_candidates().first(), Some(&c.daemon_binary_name()));
            assert_eq!(c.cli_binary_candidates().first(), Some(&c.cli_binary_name()));
        }
    }

    #[test]
    fn every_channel_also_answers_to_the_name_cargo_gives_it() {
        // `[[bin]] name = "farcoolerd"` is what a build produces whatever
        // channel stamped it, and `build-linux.sh`, `release.yml` and
        // `build-app.sh` all copy that name out of `target/` unchanged. A
        // lookup that accepted only the channel name would mean a checkout
        // stops being able to find what it just built the moment it is not
        // stable.
        for c in ALL_CHANNELS {
            assert!(c.daemon_binary_candidates().contains(&"farcoolerd"), "{c:?}");
            assert!(c.cli_binary_candidates().contains(&"farcooler"), "{c:?}");
        }
    }

    #[test]
    fn stable_looks_for_exactly_one_name() {
        // Its channel name and cargo's name are the same string, and a list
        // that repeated it would make every caller do redundant work and
        // every error message list a path twice.
        assert_eq!(Channel::Stable.daemon_binary_candidates(), &["farcoolerd"]);
        assert_eq!(Channel::Stable.cli_binary_candidates(), &["farcooler"]);
    }
}
